// 단축키 On/Off 설정 반영 React 모델
import { useEffect, useState } from "react";

export function HotkeyController() {
  const [allowSingleHotkey, setAllowSingleHotkey] = useState(false);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // 텍스트 입력 폼 안에서는 작동 제외
      const target = e.target as HTMLElement;
      if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA') return;

      if (e.key === 's' || e.key === 'S') {
        if (!allowSingleHotkey) {
          // 단일 단축키 비허용 상태일 때는 차단
          return;
        }
        alert('단일 단축키 s가 작동하여 스캔을 시작합니다!');
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [allowSingleHotkey]);

  return (
    <div className="p-4 border rounded-xl bg-slate-50 space-y-3">
      <div className="flex items-center justify-between">
        <div>
          <h5 className="font-bold text-sm text-slate-900">단일 자판 단축키 제어 설정 [KWCAG 2.2 대응]</h5>
          <p className="text-xs text-slate-500">지정키 'S' 단축 작동여부를 끄거나 켤 수 있습니다.</p>
        </div>
        <button
          onClick={() => setAllowSingleHotkey(!allowSingleHotkey)}
          className={`px-3 py-1.5 rounded text-xs font-semibold ${allowSingleHotkey ? 'bg-red-100 text-red-700' : 'bg-slate-200 text-slate-700'}`}
        >
          {allowSingleHotkey ? "단축키 비활성화하기" : "단축키 활성화하기"}
        </button>
      </div>
    </div>
  );
}

// 세션 시간 연장 인터페이스 예시
import { useState, useEffect } from "react";

export function SessionTimeoutController() {
  const [timeLeft, setTimeLeft] = useState(60); // 60초 예시

  useEffect(() => {
    if (timeLeft <= 0) return;
    const timer = setInterval(() => setTimeLeft(prev => prev - 1), 1000);
    return () => clearInterval(timer);
  }, [timeLeft]);

  const handleExtend = () => {
    setTimeLeft(120); // 120초로 시간 연장
  };

  return (
    <div className="p-4 border border-orange-200 bg-orange-50/50 rounded-xl flex justify-between items-center text-sm">
      <div className="flex items-center space-x-2">
        <span className="w-2 h-2 rounded-full bg-orange-500 animate-pulse"></span>
        <span className="text-slate-700 font-medium">안전한 세션 유지 시간: <strong className="text-orange-600 font-mono">{timeLeft}초</strong> 남음</span>
      </div>
      <button 
        onClick={handleExtend}
        className="px-3 py-1.5 bg-white border border-orange-300 rounded-md text-xs font-bold text-orange-700 hover:bg-orange-100 transition-colors"
      >
        시간 연장하기
      </button>
    </div>
  );
}

// 슬라이드 배너 재생/정지 제어기
import { useState, useEffect } from "react";

export function CarouselWithControls() {
  const [isPlaying, setIsPlaying] = useState(true);
  const [currentSlide, setCurrentSlide] = useState(1);

  useEffect(() => {
    if (!isPlaying) return;
    const interval = setInterval(() => {
      setCurrentSlide(prev => (prev % 3) + 1);
    }, 3000);
    return () => clearInterval(interval);
  }, [isPlaying]);

  return (
    <div className="p-4 bg-slate-900 text-slate-100 rounded-xl space-y-3">
      <div className="flex items-center justify-between">
        <h5 className="font-bold text-sm">자동 순환 배너 광고 (슬라이드 {currentSlide}/3)</h5>
        <button 
          onClick={() => setIsPlaying(!isPlaying)}
          aria-label={isPlaying ? "자동 롤링 일시정지" : "자동 롤링 시작"}
          className="px-2.5 py-1 bg-slate-800 text-xs rounded hover:bg-slate-700 font-semibold"
        >
          {isPlaying ? "일시정지" : "자동재생"}
        </button>
      </div>
      <div className="h-12 flex items-center justify-center bg-slate-800 rounded font-bold text-xs text-slate-300">
        배너 컨텐츠 #{currentSlide} 내용 표시중...
      </div>
    </div>
  );
}

