// 폼 에러 핸들링 접근성 모범 예시
import { useState, useRef } from "react";

export function RegistrationForm() {
  const [email, setEmail] = useState("");
  const [error, setError] = useState<string | null>(null);
  const emailRef = useRef<HTMLInputElement>(null);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!email.includes("@")) {
      setError("이메일 형식에 @ 기호가 누락되었습니다. 다시 입력해 주십시오.");
      emailRef.current?.focus(); // 오류가 있는 입력 칸으로 초점 즉시 강제 이동
    } else {
      setError(null);
      alert("성공적으로 접수되었습니다!");
    }
  };

  return (
    <form onSubmit={handleSubmit} className="p-4 border rounded-xl bg-white space-y-4">
      <div className="flex flex-col gap-1.5">
        <label htmlFor="user-email" className="text-xs font-bold text-slate-800">이메일 주소 입력</label>
        <input 
          id="user-email"
          ref={emailRef}
          type="text" 
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          aria-invalid={error ? "true" : "false"}
          aria-describedby={error ? "email-error-msg" : undefined}
          className="border rounded p-2 text-sm focus:ring-2 focus:ring-slate-900 focus:outline-none"
        />
        {error && (
          <p id="email-error-msg" className="text-xs text-red-600 font-bold flex items-center gap-1">
            <AlertCircle className="w-3.5 h-3.5" /> {error}
          </p>
        )}
      </div>
      <button type="submit" className="px-4 py-2 bg-slate-900 text-white rounded text-xs font-bold">인증 완료</button>
    </form>
  );
}

