// 반복 정보 자동 동기화 기능 예시
import { useState } from "react";

export function DuplicateEntryPreventer() {
  const [senderName, setSenderName] = useState("");
  const [receiverName, setReceiverName] = useState("");
  const [isSame, setIsSame] = useState(false);

  const handleCheckboxChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const checked = e.target.checked;
    setIsSame(checked);
    if (checked) {
      setReceiverName(senderName); // 이전 입력 정보를 자동으로 배정
    } else {
      setReceiverName("");
    }
  };

  return (
    <div className="p-4 border rounded-xl bg-white space-y-4 text-xs">
      <div className="space-y-2">
        <label htmlFor="sender-name" className="block font-bold text-slate-800">1. 주문자 성함</label>
        <input 
          id="sender-name" 
          type="text" 
          value={senderName} 
          onChange={(e) => setSenderName(e.target.value)}
          className="border rounded p-2 w-full text-xs"
          placeholder="주문자 성함 기입"
        />
      </div>

      <div className="flex items-center gap-2 p-2 bg-slate-50 rounded border">
        <input 
          type="checkbox" 
          id="sync-info" 
          checked={isSame}
          onChange={handleCheckboxChange}
          className="w-4 h-4"
        />
        <label htmlFor="sync-info" className="font-semibold text-slate-700 cursor-pointer">
          주문자 정보와 동일하게 배송지 수령인을 채웁니다 (KWCAG 2.2 반복 입력 최소화)
        </label>
      </div>

      <div className="space-y-2">
        <label htmlFor="receiver-name" className="block font-bold text-slate-800">2. 수령인 성함</label>
        <input 
          id="receiver-name" 
          type="text" 
          value={receiverName} 
          onChange={(e) => setReceiverName(e.target.value)}
          className="border rounded p-2 w-full text-xs"
          placeholder="수령인 성함 기입"
          disabled={isSame} // 동기화 중일 땐 비활성화하여 오탈 방지
        />
      </div>
    </div>
  );
}

